parameters.functionCode:
// Render HTML email nhắc lịch phỏng vấn theo mốc (24h, 2h, 15m)
const body = $input.item.json.body || {};
const {
  interviewId,
  reminderType,
  candidateEmail,
  candidateName,
  jobTitle,
  companyName,
  interviewType,
  interviewTypeLabel,
  scheduledAt,
  durationMin,
  location,
  meetingLink,
  interviewerName
} = body;

const isOnline = Boolean(meetingLink);
const typeText = interviewTypeLabel || 'Phỏng vấn chuyên môn';
const formattedTime = new Date(scheduledAt).toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });

let bannerText = 'Buổi phỏng vấn của bạn sắp diễn ra';
let subject = `[JobMatch] Nhắc lịch: ${typeText} - ${jobTitle} (${companyName})`;

if (reminderType === '24h') {
  bannerText = 'Buổi phỏng vấn của bạn sẽ diễn ra vào ngày mai';
  subject = `[JobMatch] Nhắc lịch (Ngày mai): ${typeText} - ${jobTitle} (${companyName})`;
} else if (reminderType === '2h') {
  bannerText = 'Buổi phỏng vấn của bạn sẽ diễn ra sau 2 giờ nữa';
  subject = `[JobMatch] Nhắc lịch (2 giờ nữa): ${typeText} - ${jobTitle} (${companyName})`;
} else if (reminderType === '15m') {
  bannerText = 'Buổi phỏng vấn sắp bắt đầu trong 15 phút tới!';
  subject = `[JobMatch] Sắp bắt đầu (15 phút nữa): ${typeText} - ${jobTitle} (${companyName})`;
}

const html = `
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 24px; border: 1px solid #e2e8f0; border-radius: 12px; background-color: #ffffff; color: #1e293b;">
  <div style="text-align: center; margin-bottom: 24px;">
    <h2 style="color: #4338ca; margin: 0; font-size: 22px;">JobMatch VN</h2>
    <p style="color: #64748b; font-size: 13px; margin: 4px 0 0 0;">Cầu nối việc làm thông minh</p>
  </div>

  <div style="background-color: #e0e7ff; border-radius: 8px; padding: 12px 16px; margin-bottom: 20px; text-align: center;">
    <span style="color: #3730a3; font-weight: 700; font-size: 15px;">⏰ ${bannerText}</span>
  </div>

  <p style="font-size: 15px; line-height: 1.6;">Xin chào <strong>${candidateName || 'Ứng viên'}</strong>,</p>
  <p style="font-size: 15px; line-height: 1.6;">
    Hệ thống xin nhắc bạn về buổi <strong>${typeText}</strong> cho vị trí <strong>${jobTitle}</strong> tại <strong>${companyName}</strong>.
  </p>

  <div style="background-color: #f8fafc; border-left: 4px solid #4338ca; padding: 16px; border-radius: 6px; margin: 20px 0;">
    <p style="margin: 0 0 8px 0; font-size: 14px;"><strong>Thời gian:</strong> ${formattedTime} (${durationMin || 60} phút)</p>
    <p style="margin: 0 0 8px 0; font-size: 14px;"><strong>Hình thức:</strong> ${isOnline ? 'Online (Google Meet)' : 'Trực tiếp'}</p>
    ${location ? `<p style="margin: 0 0 8px 0; font-size: 14px;"><strong>Địa điểm:</strong> ${location}</p>` : ''}
    ${interviewerName ? `<p style="margin: 0; font-size: 14px;"><strong>Người phỏng vấn / Hội đồng:</strong> ${interviewerName}</p>` : ''}
  </div>

  ${isOnline && meetingLink ? `
  <div style="margin: 24px 0; padding: 16px; background-color: #eef2ff; border: 1px dashed #6366f1; border-radius: 8px; text-align: center;">
    <p style="margin: 0 0 8px 0; font-size: 13px; color: #4338ca; font-weight: 600;">Phòng họp trực tuyến:</p>
    <a href="${meetingLink}" target="_blank" style="display: inline-block; background-color: #4338ca; color: #ffffff; padding: 10px 24px; font-size: 14px; font-weight: 600; text-decoration: none; border-radius: 8px;">
      Vào Google Meet ngay
    </a>
    <p style="margin: 8px 0 0 0; font-size: 12px; color: #64748b; word-break: break-all;">${meetingLink}</p>
  </div>
  ` : ''}

  <div style="background-color: #fefce8; border: 1px solid #fef08a; border-radius: 8px; padding: 12px; font-size: 13px; color: #854d0e; line-height: 1.5;">
    💡 <strong>Lưu ý:</strong> Vui lòng chuẩn bị trang phục lịch sự, kiểm tra kết nối mạng Internet, micro và webcam trước giờ phỏng vấn ít nhất 5–10 phút để buổi gặp diễn ra thuận lợi nhất.
  </div>

  <hr style="border: none; border-top: 1px solid #f1f5f9; margin: 24px 0;" />
  <p style="font-size: 12px; color: #94a3b8; text-align: center; margin: 0;">
    Email nhắc lịch tự động từ nền tảng JobMatch VN. Chúc bạn có một buổi phỏng vấn thật thành công!
  </p>
</div>`;

return { json: { html, subject } };
